#!/usr/bin/env node
// Test stand-in for `vite build` (fixture only). Honors --base, --outDir and --emptyOutDir like Vite:
// bundles index.html's module entry plus the bare `three` import into hashed assets and copies public/.
import { createHash } from 'node:crypto'
import fs from 'node:fs'
import path from 'node:path'

const args = process.argv.slice(2)
if (args[0] !== 'build') { console.error('fixture vite supports only `vite build`'); process.exit(1) }
const option = name => { const i = args.indexOf(name); return i === -1 ? undefined : args[i + 1] }
const base = option('--base') ?? '/'
const outDir = path.resolve(option('--outDir') ?? 'dist')
if (args.includes('--emptyOutDir') || !option('--outDir')) fs.rmSync(outDir, { recursive: true, force: true })
fs.mkdirSync(path.join(outDir, 'assets'), { recursive: true })
const hash = text => createHash('sha256').update(text).digest('hex').slice(0, 8)
const three = fs.readFileSync(path.resolve('node_modules/three/build/three.module.js'), 'utf8')
const threeName = `three-${hash(three)}.js`
fs.writeFileSync(path.join(outDir, 'assets', threeName), three)
let html = fs.readFileSync('index.html', 'utf8')
const entry = /<script type="module" src="\/([^"]+)"><\/script>/.exec(html)
const main = fs.readFileSync(entry[1], 'utf8').replace(/from 'three'/g, `from './${threeName}'`)
const mainName = `index-${hash(main)}.js`
fs.writeFileSync(path.join(outDir, 'assets', mainName), main)
html = html.replace(entry[0], `<script type="module" crossorigin src="${base}assets/${mainName}"></script>`)
html = html.replace('href="/favicon.png"', `href="${base}favicon.png"`)
fs.writeFileSync(path.join(outDir, 'index.html'), html)
if (fs.existsSync('public')) fs.cpSync('public', outDir, { recursive: true })
// Like tsc -b or a bundler cache, leave a file in the working directory: it must land in the scratch copy, never the project.
fs.writeFileSync('.fixture-build-cache', String(Date.now()))
console.log(`vite (fixture) built ${path.relative(process.cwd(), outDir) || outDir}`)
